1	// Package deploy generates Kubernetes deployment manifests (a kustomize
2	// base + overlays tree) for a previously scaffolded integration. It reads
3	// the committed .intropy/scaffold.json record, re-fetches the exact
4	// template version it pins, and renders the template's manifests/
5	// directory with the template package's template machinery.
6	package deploy
7	
8	import (
9		"context"
10		"encoding/json"
11		"errors"
12		"fmt"
13		"io"
14		"net/http"
15		"os"
