72	func (o *CreateOptions) applyDefaults() {
73		if o.StartDir == "" {
74			o.StartDir = "."
75		}
76		if o.Stdin == nil {
77			o.Stdin = os.Stdin
78		}
79		if o.UserAgent == "" {
80			o.UserAgent = "intropy-cli"
81		}
82	}
