84	// Create generates the deployment manifests: locate scaffold.json, download
85	// the pinned template, load manifests/template.yaml, resolve values (seeded
86	// from the scaffold record, with optional interactive prompting), render
87	// manifests/skeleton into the output directory.
88	func Create(ctx context.Context, opts CreateOptions) error {
89		opts.applyDefaults()
90	
91		scaffold, projectRoot, err := template.FindScaffold(opts.StartDir)
92		if err != nil {
93			if errors.Is(err, template.ErrScaffoldNotFound) {
94				return fmt.Errorf("%w\nThis project was scaffolded before deployment metadata existed. Re-scaffold it with 'intropy int create', or commit a minimal %s:\n  {\"schemaVersion\":1,\"template\":\"<template>\",\"owner\":\"integrio-intropy\",\"repo\":\"intropy-templates\",\"version\":\"<tag>\",\"values\":{\"name\":\"<name>\"}}", err, template.ScaffoldRelPath)
95			}
96			return err
97		}
98		if scaffold.SchemaVersion > template.ScaffoldSchemaVersion {
99			return fmt.Errorf("%s has schemaVersion %d, but this CLI supports up to %d; upgrade intropy", template.ScaffoldRelPath, scaffold.SchemaVersion, template.ScaffoldSchemaVersion)
100		}
101		owner, repo := scaffold.Owner, scaffold.Repo
102		if opts.Owner != "" {
103			owner = opts.Owner
104		}
105		if opts.Repo != "" {
106			repo = opts.Repo
107		}
108	
109		tag := scaffold.Version
110		if opts.Version != "" {
111			tag = opts.Version
112		}
113		if tag == "" {
114			return fmt.Errorf("%s does not pin a template version; pass --version", template.ScaffoldRelPath)
115		}
116	
117		gh := template.NewGitHubClient(opts.HTTP, opts.UserAgent, opts.GitHubBaseURL)
118		fmt.Fprintf(opts.Stderr, "fetching %s/%s@%s\n", owner, repo, tag)
119		templateRoot, cleanup, err := template.DownloadTemplate(ctx, gh, owner, repo, tag, scaffold.Template, "intropy-manifests-*")
120		if err != nil {
121			return err
122		}
123		defer cleanup()
124	
125		manifestsRoot := filepath.Join(templateRoot, manifestDirName)
126		skelRoot := filepath.Join(manifestsRoot, skeletonDirName)
127		if !dirExists(skelRoot) || !fileExists(filepath.Join(manifestsRoot, templateManifestName)) {
128			return fmt.Errorf("template %q at %s does not include deployment manifest templates (%s/); pass --version <newer tag> or update the template", scaffold.Template, tag, manifestDirName)
129		}
130	
131		tmpl, err := template.LoadTemplate(filepath.Join(manifestsRoot, templateManifestName))
132		if err != nil {
133			return err
134		}
135		values, err := resolveManifestValues(tmpl, scaffold, opts)
136		if err != nil {
137			return err
138		}
139	
140		outputDir := opts.OutputDir
141		if outputDir == "" {
142			outputDir = filepath.Join(projectRoot, defaultOutputDirName)
143		}
144		if err := template.EnsureOutputDir(outputDir, opts.Force); err != nil {
145			return err
146		}
147		if err := template.Render(skelRoot, outputDir, values); err != nil {
148			return err
149		}
150		fmt.Fprintf(opts.Stderr, "wrote deployment manifests to %s (template %s@%s)\n", outputDir, scaffold.Template, tag)
151	
152		return maybeWriteCreateResult(opts, scaffold, owner, repo, tag, outputDir, values)
153	}
154	
155	// resolveManifestValues resolves the manifest template's parameters, seeded
156	// by the scaffold record: scaffold values whose names match declared
157	// parameters auto-fill (no re-prompt) but yield to --values/--set. The full
158	// scaffold value map is exposed under the reserved "scaffold" key — added
159	// after Resolve so it never contaminates JSON Schema validation.
160	func resolveManifestValues(tmpl *template.Template, scaffold *template.Scaffold, opts CreateOptions) (map[string]any, error) {
161		declared := map[string]bool{}
162		for _, f := range tmpl.Fields() {
163			if f.Name == scaffoldValuesKey {
164				return nil, fmt.Errorf("manifest template declares reserved parameter %q", scaffoldValuesKey)
165			}
166			declared[f.Name] = true
167		}
168		if _, ok := tmpl.Spec.Values[scaffoldValuesKey]; ok {
169			return nil, fmt.Errorf("manifest template declares reserved spec.values entry %q", scaffoldValuesKey)
170		}
171	
172		seed := map[string]any{}
173		for k, v := range scaffold.Values {
174			if declared[k] {
175				seed[k] = v
176			}
177		}
178	
179		prompter := template.AutoPrompter(opts.Stdin, opts.Stderr, opts.NoInput)
180		values, err := template.ResolveLayered(tmpl, seed, opts.Files, opts.Stdin, opts.SetValues, prompter)
181		if err != nil {
182			return nil, err
183		}
184		values[scaffoldValuesKey] = scaffold.Values
185		return values, nil
186	}
187	
188	func maybeWriteCreateResult(opts CreateOptions, scaffold *template.Scaffold, owner, repo, tag, outputDir string, values map[string]any) error {
189		if opts.OutputJSON == "" {
190			return nil
191		}
192		absOut, err := filepath.Abs(outputDir)
193		if err != nil {
194			absOut = outputDir
195		}
196		result := CreateResult{
197			Template:  scaffold.Template,
198			Owner:     owner,
199			Repo:      repo,
200			Version:   tag,
201			OutputDir: absOut,
202			Values:    values,
203		}
204		data, err := json.MarshalIndent(result, "", "  ")
205		if err != nil {
206			return fmt.Errorf("write --output-json: %w", err)
207		}
208		data = append(data, '\n')
209		if opts.OutputJSON == "-" {
210			if _, err := opts.Stdout.Write(data); err != nil {
211				return fmt.Errorf("write --output-json: %w", err)
212			}
213			return nil
214		}
215		if err := os.WriteFile(opts.OutputJSON, data, 0o644); err != nil {
216			return fmt.Errorf("write --output-json: %w", err)
217		}
218		return nil
219	}
