package system

// TopicKey identifies a topic within the system: the pub/sub component it
// lives on plus the topic name. Two scaffolds naming the same key declare
// the two halves of one contract.
type TopicKey struct {
	Pubsub string `json:"pubsub"`
	Name   string `json:"topic"`
}

// Topic is one assembled topic: its key, the C# contract type its messages
// carry, and the identifier it gets in the generated Topics class.
type Topic struct {
	TopicKey
	Contract string `json:"contract"`
	Field    string `json:"-"`
}

// Component is one assembled system block.
type Component struct {
	AppID string   `json:"name"` // the AddExtractor/AddLoader argument
	Kind  string   `json:"kind"` // template.BlockKindExtractor or BlockKindLoader
	Topic TopicKey `json:"-"`
	Path  string   `json:"path"` // scaffold directory, for error messages
}

// SharedLibrary is the workspace's contract project: referenced by the
// host, never declared as a component.
type SharedLibrary struct {
	Path string // scaffold directory
	Name string // project name; also the namespace and csproj basename
}

// Model is the assembled system declaration `sys create` generates code
// from. Name, ProjectName and SystemClass are filled in around the
// template render; Assemble leaves them empty.
type Model struct {
	Name        string // kebab-case system name
	ProjectName string // template-derived PascalCase name
	SystemClass string // template-derived ISystemDefinition class name
	Components  []Component
	Topics      []Topic // sorted by (Pubsub, Name)
	Shared      SharedLibrary
}

package system

import (
	"errors"
	"fmt"
	"path/filepath"
	"sort"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// ErrNoComponents is returned when the workspace scan finds no scaffold
// record `sys create` can assemble into a component.
var ErrNoComponents = errors.New("no assemblable integration scaffolds found")

// Assemble classifies workspace scaffold records into a system model:
// shared-library records become the referenced contract project,
// extractor/loader records become components, and everything else is
// skipped through warnf. The returned model's Name/ProjectName/SystemClass
// are left empty — the caller fills them around the template render.
func Assemble(entries []template.ScaffoldEntry, warnf func(format string, args ...any)) (*Model, error) {
	var (
		components []Component
		shared     []SharedLibrary
		byAppID    = map[string]string{}         // appId -> scaffold dir
		byTopic    = map[TopicKey]Topic{}        // key -> first-seen topic
		firstDir   = map[TopicKey]string{}       // key -> dir that defined it
	)

	for _, e := range entries {
		switch {
		case e.Role == template.RoleSharedLibrary:
			name, err := stringValue(e, "name")
			if err != nil {
				return nil, err
			}
			shared = append(shared, SharedLibrary{Path: e.Path, Name: name})
			continue
		case e.Role == template.RoleSystemHost:
			warnf("skipping %s: an existing system host", e.Path)
			continue
		case e.BlockKind == "":
			warnf("skipping %s: scaffold record has no block kind — re-scaffold with a newer template release to include it", e.Path)
			continue
		case e.BlockKind != template.BlockKindExtractor && e.BlockKind != template.BlockKindLoader:
			warnf("skipping %s: unsupported block kind %q (sys create assembles extractors and loaders only)", e.Path, e.BlockKind)
			continue
		}

		appID, err := stringValue(e, "appId")
		if err != nil {
			return nil, err
		}
		topic, err := stringValue(e, "topic")
		if err != nil {
			return nil, err
		}
		contract, err := stringValue(e, "contract")
		if err != nil {
			return nil, fmt.Errorf("%w\nRe-scaffold this integration with a template release that records the contract type, or add \"contract\": \"<TypeName>\" to the record's values.", err)
		}
		pubsub, err := stringValueDefault(e, "pubsub", "pubsub")
		if err != nil {
			return nil, err
		}

		if prev, ok := byAppID[appID]; ok {
			return nil, fmt.Errorf("duplicate component name %q: declared by both %s and %s (component names must be unique in a system)", appID, prev, e.Path)
		}
		byAppID[appID] = e.Path

		key := TopicKey{Pubsub: pubsub, Name: topic}
		if seen, ok := byTopic[key]; ok {
			if seen.Contract != contract {
				return nil, fmt.Errorf("topic %q on pubsub %q has conflicting contracts: %q (%s) vs %q (%s)", topic, pubsub, seen.Contract, firstDir[key], contract, e.Path)
			}
		} else {
			byTopic[key] = Topic{TopicKey: key, Contract: contract, Field: pascalIdent(topic)}
			firstDir[key] = e.Path
		}

		components = append(components, Component{AppID: appID, Kind: e.BlockKind, Topic: key, Path: e.Path})
	}

	if len(components) == 0 {
		return nil, fmt.Errorf("%w in this directory\nScaffold extractors and loaders first ('intropy int create extractor -n <Name> -s topic=<topic> ...'), then run 'intropy sys create' from the workspace root.", ErrNoComponents)
	}
	switch {
	case len(shared) == 0:
		return nil, fmt.Errorf("no shared contracts project found (template role %q): Topics.cs needs the contract types\nComponents scaffolded from the official extractor/loader templates create a sibling Models/ project automatically.", template.RoleSharedLibrary)
	case len(shared) > 1:
		dirs := make([]string, len(shared))
		for i, s := range shared {
			dirs[i] = s.Path
		}
		return nil, fmt.Errorf("found %d shared contract projects (%s); a system host references exactly one — remove or consolidate before re-running", len(shared), strings.Join(dirs, ", "))
	}

	topics := make([]Topic, 0, len(byTopic))
	for _, t := range byTopic {
		topics = append(topics, t)
	}
	sort.Slice(topics, func(i, j int) bool {
		if topics[i].Pubsub != topics[j].Pubsub {
			return topics[i].Pubsub < topics[j].Pubsub
		}
		return topics[i].Name < topics[j].Name
	})

	fields := map[string]TopicKey{}
	for _, t := range topics {
		if prev, ok := fields[t.Field]; ok {
			return nil, fmt.Errorf("topics %q and %q both map to field %s in Topics.cs; rename one topic", prev.Name, t.Name, t.Field)
		}
		fields[t.Field] = t.TopicKey
	}

	return &Model{Components: components, Topics: topics, Shared: shared[0]}, nil
}

// stringValue returns values[key] as a non-empty string, with errors that
// name the record so the user knows which project to fix.
func stringValue(e template.ScaffoldEntry, key string) (string, error) {
	record := filepath.Join(e.Path, filepath.FromSlash(template.ScaffoldRelPath))
	v, ok := e.Values[key]
	if !ok {
		return "", fmt.Errorf("%s: values.%s is missing", record, key)
	}
	s, ok := v.(string)
	if !ok {
		return "", fmt.Errorf("%s: values.%s has type %T, expected string", record, key, v)
	}
	if s == "" {
		return "", fmt.Errorf("%s: values.%s is empty", record, key)
	}
	return s, nil
}

// stringValueDefault is stringValue with a fallback for records that
// predate the value being recorded.
func stringValueDefault(e template.ScaffoldEntry, key, fallback string) (string, error) {
	if _, ok := e.Values[key]; !ok {
		return fallback, nil
	}
	return stringValue(e, key)
}

// pascalIdent converts a DNS-ish name to a C# identifier: segments split
// on '-', '.' and '_' are title-cased and joined ("order-events" →
// "OrderEvents").
func pascalIdent(s string) string {
	segments := strings.FieldsFunc(s, func(r rune) bool {
		return r == '-' || r == '.' || r == '_'
	})
	var b strings.Builder
	for _, seg := range segments {
		b.WriteString(strings.ToUpper(seg[:1]))
		b.WriteString(seg[1:])
	}
	return b.String()
}

package system

import (
	"bytes"
	"fmt"
	"os"
	"path/filepath"
	"text/template"
)

// The generated declaration files. Deliberately namespace-less: the host
// project is small enough that the declaration reads as one document, and
// discovery reflects over the assembly regardless.
const topicsFileTmpl = `using Intropy.Topology;
using {{ .Shared.Name }};

/// <summary>The system's topics, each defined once and shared by every component that touches it.</summary>
public static class Topics
{
{{- range $i, $t := .Topics }}
{{- if $i }}
{{ end }}
    /// <summary>{{ $t.Contract }} messages on topic '{{ $t.Name }}' (pubsub '{{ $t.Pubsub }}').</summary>
    public static readonly TopicRef<{{ $t.Contract }}> {{ $t.Field }} = TopicRef<{{ $t.Contract }}>.Define("{{ $t.Pubsub }}", "{{ $t.Name }}");
{{- end }}
}
`

const systemClassFileTmpl = `using Intropy.Topology;

/// <summary>The {{ .Name }} system: what exists, and what connects it.</summary>
public sealed class {{ .SystemClass }} : ISystemDefinition
{
    public string SystemName => "{{ .Name }}";

    public void Define(SystemBuilder builder)
    {
{{- range .Components }}
        builder.{{ .Add }}("{{ .AppID }}").{{ .Edge }}(Topics.{{ .Field }});
{{- end }}
    }
}
`

var (
	topicsFile      = template.Must(template.New("Topics.cs").Parse(topicsFileTmpl))
	systemClassFile = template.Must(template.New("SystemClass.cs").Parse(systemClassFileTmpl))
)

// componentView is a Component with its builder call and topic field
// resolved for the system class template.
type componentView struct {
	AppID string
	Add   string // AddExtractor | AddLoader
	Edge  string // Publishes | Subscribes
	Field string // the Topics.cs field the component touches
}

// writeTopicsFile overwrites <dir>/Topics.cs with the assembled topic
// declarations.
func writeTopicsFile(dir string, m *Model) error {
	return renderTo(filepath.Join(dir, "Topics.cs"), topicsFile, m)
}

// writeSystemClassFile overwrites <dir>/<SystemClass>.cs with the assembled
// system definition. It refuses to create the file: the rendered template
// must have left the placeholder, or its name derivation disagrees with
// this CLI and the write would add a second ISystemDefinition instead of
// replacing the placeholder.
func writeSystemClassFile(dir string, m *Model) error {
	path := filepath.Join(dir, m.SystemClass+".cs")
	if _, err := os.Stat(path); err != nil {
		return fmt.Errorf("template rendered no %s.cs placeholder: the template's systemClass derivation disagrees with this CLI; upgrade intropy or pass --version <compatible tag>", m.SystemClass)
	}

	views := make([]componentView, len(m.Components))
	fieldByKey := map[TopicKey]string{}
	for _, t := range m.Topics {
		fieldByKey[t.TopicKey] = t.Field
	}
	for i, c := range m.Components {
		v := componentView{AppID: c.AppID, Field: fieldByKey[c.Topic]}
		if c.Kind == "extractor" {
			v.Add, v.Edge = "AddExtractor", "Publishes"
		} else {
			v.Add, v.Edge = "AddLoader", "Subscribes"
		}
		views[i] = v
	}

	return renderTo(path, systemClassFile, struct {
		Name        string
		SystemClass string
		Components  []componentView
	}{m.Name, m.SystemClass, views})
}

func renderTo(path string, tmpl *template.Template, data any) error {
	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, data); err != nil {
		return fmt.Errorf("generate %s: %w", filepath.Base(path), err)
	}
	if err := os.WriteFile(path, buf.Bytes(), 0o644); err != nil {
		return fmt.Errorf("generate %s: %w", filepath.Base(path), err)
	}
	return nil
}

package system

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// insertProjectReference inserts an ItemGroup referencing the shared
// contracts project immediately before the closing </Project> tag. The
// csproj was rendered by this run seconds earlier, so its shape is known;
// textual insertion preserves the template's comments and formatting,
// which encoding/xml round-tripping would destroy. include is
// slash-separated and relative to the csproj's directory.
func insertProjectReference(csprojPath, include string) error {
	data, err := os.ReadFile(csprojPath)
	if err != nil {
		return fmt.Errorf("reference shared contracts project: %w", err)
	}
	content := string(data)
	idx := strings.LastIndex(content, "</Project>")
	if idx < 0 {
		return fmt.Errorf("reference shared contracts project: rendered %s has no </Project> closing tag", filepath.Base(csprojPath))
	}

	// IsAspireProjectResource="false" keeps the Aspire AppHost from
	// treating the class library as an orchestrated resource.
	itemGroup := "    <ItemGroup>\n" +
		"        <!-- Shared contracts project, referenced by `intropy sys create`. -->\n" +
		"        <ProjectReference Include=\"" + include + "\" IsAspireProjectResource=\"false\" />\n" +
		"    </ItemGroup>\n\n"

	updated := content[:idx] + itemGroup + content[idx:]
	if err := os.WriteFile(csprojPath, []byte(updated), 0o644); err != nil {
		return fmt.Errorf("reference shared contracts project: %w", err)
	}
	return nil
}

// contractsInclude computes the ProjectReference Include path from the
// host's output directory to the shared library's csproj, slash-separated.
func contractsInclude(outputDir string, shared SharedLibrary) (string, error) {
	absOut, err := filepath.Abs(outputDir)
	if err != nil {
		return "", err
	}
	absShared, err := filepath.Abs(shared.Path)
	if err != nil {
		return "", err
	}
	rel, err := filepath.Rel(absOut, absShared)
	if err != nil {
		return "", fmt.Errorf("compute path from %s to shared contracts project %s: %w", outputDir, shared.Path, err)
	}
	return filepath.ToSlash(filepath.Join(rel, shared.Name+".csproj")), nil
}

