// checkout. Not for commit: it depends on a sibling repo path.

import (
	"archive/tar"
	"bytes"
	"compress/gzip"
	"context"
	"io/fs"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

const localTemplatesDir = "/Users/robinhultman/dev/intropy/tooling/intropy-templates"

func buildRepoTarGz(t *testing.T, root string) []byte {
	t.Helper()
	var buf bytes.Buffer
	gz := gzip.NewWriter(&buf)
	tw := tar.NewWriter(gz)
	err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			if d.Name() == ".git" {
				return fs.SkipDir
			}
			return nil
		}
		rel, err := filepath.Rel(root, path)
		if err != nil {
			return err
		}
		data, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		h := &tar.Header{
			Name:     "owner-repo-local/" + filepath.ToSlash(rel),
			Mode:     0o644,
			Size:     int64(len(data)),
			Typeflag: tar.TypeReg,
		}
		if err := tw.WriteHeader(h); err != nil {
			return err
		}
		_, err = tw.Write(data)
		return err
	})
	if err != nil {
		t.Fatal(err)
	}
	if err := tw.Close(); err != nil {
		t.Fatal(err)
	}
	if err := gz.Close(); err != nil {
		t.Fatal(err)
	}
	return buf.Bytes()
}

func TestTutorialReplayAgainstLocalTemplates(t *testing.T) {
	if _, err := os.Stat(localTemplatesDir); err != nil {
		t.Skip("local intropy-templates checkout not present")
	}

	tarball := buildRepoTarGz(t, localTemplatesDir)
	mux := http.NewServeMux()
	mux.HandleFunc("/repos/o/r/tarball/vLOCAL", func(w http.ResponseWriter, r *http.Request) {
		_, _ = w.Write(tarball)
	})
	srv := httptest.NewServer(mux)
	defer srv.Close()

	ws := t.TempDir()
	var stderr bytes.Buffer

	// Chapter 1 + 2: scaffold the extractor and the loader.
	for _, block := range []struct{ tmpl, name, out string }{
		{"extractor", "OrderExtractor", "order-extractor"},
		{"loader", "OrderLoader", "order-loader"},
	} {
		err := template.Create(context.Background(), template.CreateOptions{
			Template:  block.tmpl,
			OutputDir: filepath.Join(ws, block.out),
			Version:   "vLOCAL",
			SetValues: map[string]any{
				"name": block.name, "organization": "Fluxia", "topic": "orders",
			},
			NoInput:       true,
			Stdout:        &stderr,
			Stderr:        &stderr,
			HTTP:          srv.Client(),
			Owner:         "o",
			Repo:          "r",
			GitHubBaseURL: srv.URL,
		})
		if err != nil {
			t.Fatalf("int create %s: %v\nstderr: %s", block.tmpl, err, stderr.String())
		}
	}

	// The records must carry what sys create assembles from.
	rec, err := template.LoadScaffold(filepath.Join(ws, "order-extractor", filepath.FromSlash(template.ScaffoldRelPath)))
	if err != nil {
		t.Fatal(err)
	}
	if rec.BlockKind != "extractor" || rec.DataFlow != "in" {
		t.Errorf("extractor record kind/flow = %q/%q", rec.BlockKind, rec.DataFlow)
	}
	for k, want := range map[string]string{"appId": "order-extractor", "topic": "orders", "contract": "Order", "pubsub": "pubsub"} {
		if rec.Values[k] != want {
			t.Errorf("extractor values.%s = %v, want %q", k, rec.Values[k], want)
		}
	}

	// Chapter 3: assemble the system host.
	stderr.Reset()
	err = Create(context.Background(), CreateOptions{
		Name:          "OrderFlow",
		StartDir:      ws,
		OutputDir:     filepath.Join(ws, "system-host"),
		Version:       "vLOCAL",
		Stdout:        &stderr,
		Stderr:        &stderr,
		HTTP:          srv.Client(),
		Owner:         "o",
		Repo:          "r",
		GitHubBaseURL: srv.URL,
	})
	if err != nil {
		t.Fatalf("sys create: %v\nstderr: %s", err, stderr.String())
	}

	topics, _ := os.ReadFile(filepath.Join(ws, "system-host", "Topics.cs"))
	if string(topics) != wantTopicsCS {
		t.Errorf("Topics.cs:\n%s", topics)
	}
	system, _ := os.ReadFile(filepath.Join(ws, "system-host", "OrderFlowSystem.cs"))
	if string(system) != wantSystemCS {
		t.Errorf("OrderFlowSystem.cs:\n%s", system)
	}
	csproj, _ := os.ReadFile(filepath.Join(ws, "system-host", "OrderFlow.SystemHost.csproj"))
	if !strings.Contains(string(csproj), `<ProjectReference Include="../Models/Models.csproj" IsAspireProjectResource="false" />`) {
		t.Errorf("csproj missing Models reference:\n%s", csproj)
	}
	t.Logf("stderr:\n%s", stderr.String())
	t.Logf("csproj:\n%s", csproj)
}

