func newLocalServer(t *testing.T) *httptest.Server {
	t.Helper()
	tarball := buildRepoTarGz(t, localTemplatesDir)
	mux := http.NewServeMux()
	mux.HandleFunc("/repos/o/r/tarball/vLOCAL", func(w http.ResponseWriter, r *http.Request) {
		_, _ = w.Write(tarball)
	})
	return httptest.NewServer(mux)
}

func intCreate(t *testing.T, srv *httptest.Server, ws, tmpl, name, out string, sets map[string]any) error {
	t.Helper()
	var sink bytes.Buffer
	base := map[string]any{"name": name, "organization": "Fluxia", "topic": "orders"}
	for k, v := range sets {
		base[k] = v
	}
	return template.Create(context.Background(), template.CreateOptions{
		Template: tmpl, OutputDir: filepath.Join(ws, out), Version: "vLOCAL",
		SetValues: base, NoInput: true,
		Stdout: &sink, Stderr: &sink,
		HTTP: srv.Client(), Owner: "o", Repo: "r", GitHubBaseURL: srv.URL,
	})
}

func TestTutorialReplayAgainstLocalTemplates(t *testing.T) {
	if _, err := os.Stat(localTemplatesDir); err != nil {
		t.Skip("local intropy-templates checkout not present")
	}
	srv := newLocalServer(t)
	defer srv.Close()
	ws := t.TempDir()

	// Omitting the now-required contract with --no-input must fail fast.
	if err := intCreate(t, srv, ws, "extractor", "OrderExtractor", "should-fail", nil); err == nil || !strings.Contains(err.Error(), "contract") {
		t.Fatalf("expected missing-contract error, got: %v", err)
	}
	_ = os.RemoveAll(filepath.Join(ws, "should-fail"))

	for _, b := range []struct{ tmpl, name, out string }{
		{"extractor", "OrderExtractor", "order-extractor"},
		{"loader", "OrderLoader", "order-loader"},
	} {
		if err := intCreate(t, srv, ws, b.tmpl, b.name, b.out, map[string]any{"contract": "Order"}); err != nil {
			t.Fatalf("int create %s: %v", b.tmpl, err)
		}
	}

	rec, err := template.LoadScaffold(filepath.Join(ws, "order-extractor", filepath.FromSlash(template.ScaffoldRelPath)))
	if err != nil {
		t.Fatal(err)
	}
	if rec.BlockKind != "extractor" || rec.Values["contract"] != "Order" || rec.Values["pubsub"] != "pubsub" {
		t.Errorf("extractor record = kind %q, values %v", rec.BlockKind, rec.Values)
	}

	var sink bytes.Buffer
	err = Create(context.Background(), CreateOptions{
		Name: "OrderFlow", StartDir: ws, OutputDir: filepath.Join(ws, "system-host"), Version: "vLOCAL",
		Stdout: &sink, Stderr: &sink,
		HTTP: srv.Client(), Owner: "o", Repo: "r", GitHubBaseURL: srv.URL,
	})
	if err != nil {
		t.Fatalf("sys create: %v\nstderr: %s", err, sink.String())
	}

	topics, _ := os.ReadFile(filepath.Join(ws, "system-host", "Topics.cs"))
	if string(topics) != wantTopicsCS {
		t.Errorf("Topics.cs:\n%s", topics)
	}
	system, _ := os.ReadFile(filepath.Join(ws, "system-host", "OrderFlowSystem.cs"))
	if string(system) != wantSystemCS {
		t.Errorf("OrderFlowSystem.cs:\n%s", system)
	}
	csproj, _ := os.ReadFile(filepath.Join(ws, "system-host", "OrderFlow.SystemHost.csproj"))
	if !strings.Contains(string(csproj), `<ProjectReference Include="../Models/Models.csproj" IsAspireProjectResource="false" />`) {
		t.Errorf("csproj missing Models reference:\n%s", csproj)
	}
}
EOF
